&lt;/li&gt;
&lt;li data-local-id=&quot;8ad4bb1f0374&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
