&lt;/li&gt;
&lt;li data-local-id=&quot;3913cb43b25b&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
