&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 data-local-id=&quot;28cc8938e0b9&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;heading&quot; data-prosemirror-node-block=&quot;true&quot;&gt;Technical Leadership and Strategic Expertise&lt;/h3&gt;
