&lt;/li&gt;
&lt;li data-local-id=&quot;1523639b1438&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
