&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 data-local-id=&quot;fa3a8e48ff4d&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;heading&quot; data-prosemirror-node-block=&quot;true&quot;&gt;Infrastructure Coordination and Strategic Management&lt;/h3&gt;
